USE challenge_db;

ON DUPLICATE KEY UPDATE
slug = VALUES(slug),
title = VALUES(title),
description = VALUES(description),
difficulty = VALUES(difficulty),
category = VALUES(category),
operation = VALUES(operation),
tables_json = VALUES(tables_json),
constraints_json = VALUES(constraints_json),
sample_test_cases = VALUES(sample_test_cases),
hidden_test_cases = VALUES(hidden_test_cases),
expected_result = VALUES(expected_result),
xp = VALUES(xp),
acceptance_rate = VALUES(acceptance_rate),
submission_count = VALUES(submission_count),
expected_query = VALUES(expected_query),
schema_setup = VALUES(schema_setup);
