(1,'select-all-employees','Select All Employees','Return every employee row.','easy','Basics','SELECT','["employee"]','["Use SELECT","Return all columns"]','[{"name":"Sample","expectedRows":5}]','[{"name":"All employees"}]','{"columns":["id","name","salary","department_id"]}',10,95,1842,'SELECT * FROM employee;','practice_db.employee'),
