(20,'all-customers-and-orders','All Customers and Their Orders','Return all customers with any orders.','medium','Joins','LEFT JOIN','["customers","orders"]','["Use LEFT JOIN","Include customers without orders"]','[{"name":"All customers"}]','[{"name":"Null orders"}]','{"columns":["customer_name","order_id"]}',20,67,980,'SELECT c.name AS customer_name, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id ORDER BY c.id, o.id;','practice_db.customers, practice_db.orders'),
