(24,'employees-above-average-salary','Employees Above Average Salary','Return employees earning above company average.','medium','Subquery','Scalar','["employee"]','["Use scalar subquery"]','[{"name":"Above average"}]','[{"name":"Average recalculation"}]','{"columns":["name","salary"]}',20,68,760,'SELECT name, salary FROM employee WHERE salary > (SELECT AVG(salary) FROM employee) ORDER BY salary DESC;','practice_db.employee'),
