(28,'create-employee-summary','Create Employee Summary','Create a view summarizing employees by department.','medium','Views','CREATE VIEW','["employee"]','["Use CREATE VIEW","Name it employee_summary"]','[{"name":"View created"}]','[{"name":"View columns"}]','{"columns":["department","employee_count","average_salary"]}',20,63,360,'CREATE VIEW employee_summary AS SELECT department, COUNT(*) AS employee_count, AVG(salary) AS average_salary FROM employee GROUP BY department;','practice_db.employee'),
