(30,'rank-employees-by-salary','Rank Employees by Salary','Assign row numbers by salary.','medium','Window','ROW_NUMBER','["employee"]','["Use ROW_NUMBER"]','[{"name":"Row numbers"}]','[{"name":"Descending salary"}]','{"columns":["name","salary","salary_row"]}',20,65,620,'SELECT name, salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS salary_row FROM employee;','practice_db.employee'),
