(34,'find-next-order','Find Next Order','Use LEAD to show the next order for each customer.','hard','Window','LEAD','["orders"]','["Use LEAD","Partition by customer"]','[{"name":"Next order"}]','[{"name":"Last null"}]','{"columns":["customer_id","id","next_order_id"]}',30,41,260,'SELECT customer_id, id, LEAD(id) OVER (PARTITION BY customer_id ORDER BY order_date) AS next_order_id FROM orders;','practice_db.orders'),
