(36,'employee-hierarchy','Employee Hierarchy','Use a recursive CTE to traverse employees.','hard','CTE','Recursive CTE','["employee"]','["Use WITH RECURSIVE"]','[{"name":"Hierarchy rows"}]','[{"name":"Depth ordering"}]','{"columns":["id","name","level"]}',30,36,210,'WITH RECURSIVE employee_tree AS (SELECT id, name, manager_id, 1 AS level FROM employee WHERE manager_id IS NULL UNION ALL SELECT e.id, e.name, e.manager_id, et.level + 1 FROM employee e JOIN employee_tree et ON e.manager_id = et.id) SELECT id, name, level FROM employee_tree;','practice_db.employee'),
