(57,'recursive-category-tree','Recursive Category Tree','Use a recursive CTE for product categories.','hard','CTE','Recursive CTE','["categories"]','["Use WITH RECURSIVE"]','[{"name":"Category tree"}]','[{"name":"Depth"}]','{"columns":["id","name","depth"]}',30,34,160,'WITH RECURSIVE category_tree AS (SELECT id, name, parent_id, 1 AS depth FROM categories WHERE parent_id IS NULL UNION ALL SELECT c.id, c.name, c.parent_id, ct.depth + 1 FROM categories c JOIN category_tree ct ON c.parent_id = ct.id) SELECT id, name, depth FROM category_tree;','practice_db.categories'),
(58,'case-customer-tier','Customer Tier Classification','Classify customers by total spend.','hard','Advanced','CASE','["customers","orders"]','["Use CASE","Use aggregate spend"]','[{"name":"Customer tiers"}]','[{"name":"Tier boundaries"}]','{"columns":["customer_name","tier"]}',30,56,260,'SELECT c.name AS customer_name, CASE WHEN SUM(o.total_amount) >= 5000 THEN ''Gold'' WHEN SUM(o.total_amount) >= 1000 THEN ''Silver'' ELSE ''Bronze'' END AS tier FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;','practice_db.customers, practice_db.orders'),
